WITH cte1 AS (SELECT MAX (45) OVER (PARTITION BY 500, 28 ORDER BY a1.c0 DESC) AS c0, a1.c0 AS c1 FROM tp AS a1 WHERE ('{"k": 0, "a": [3, 4, 5]}'::jsonb <@ '{"k": 2, "a": [0]}'::jsonb)), cte2 AS (SELECT (EXISTS (SELECT a2.c0 AS c0, CASE WHEN a3.c1 THEN a3.c0 ELSE '-2'::int END AS c1, a2.c0 AS c2, '1 year 2 mons 3 days 04:05:06.789'::interval AS c3)) AS c0, 5e-324::float8 AS c1 FROM (n1 AS a2 RIGHT JOIN t3 AS a3 ON ((a2.c1 = a3.c1) AND CASE WHEN FALSE THEN CASE WHEN FALSE THEN a2.c1 ELSE a2.c1 END ELSE a3.c1 END)) WHERE (SELECT BOOL_AND (FALSE) FROM t4 AS a4)) SELECT ROUND (NULLIF ((LENGTH (JSON_VALUE (NULL::jsonb, '$.a.size()')))::numeric, (COALESCE (0.5::numeric, 0.0::numeric) + TRUNC (1.5::numeric))), (-1)) AS c0, '00:00:00.000001'::interval AS c1, AGE ('2000-01-01 00:00:00+00'::timestamptz, '2000-01-01 00:00:00+00'::timestamptz) AS c2 FROM cte1 AS a5 WHERE (a5.c0 >= '200'::int);
